import static org.junit.Assert.*;

public class CSVParser_getHeaderMap_TriageGen0Test {

    @Test
    public void testGetHeaderMap_WithHeaders() throws IOException {
        // CSV content with a header row
        String csvContent = "id,name,age\n1,John,30\n2,Jane,25";
        StringReader reader = new StringReader(csvContent);

        // Using CSVFormat.DEFAULT which includes headers
        CSVFormat format = CSVFormat.DEFAULT.withHeader();

        try (CSVParser parser = CSVParser.parse(csvContent, format)) {
            Map<String, Integer> headerMap = parser.getHeaderMap();

            assertNotNull("Header map should not be null when headers are present", headerMap);
            assertEquals("Header map size should be 3", 3, headerMap.size());

            // Check if indices match the columns
            assertEquals(Integer.valueOf(0), headerMap.get("id"));
            assertEquals(Integer.valueOf(1), headerMap.get("name"));
            assertEquals(Integer.valueOf(2), headerMap.get("age"));

            // Verify it returns a copy (defensive copy check)
            headerMap.put("newKey", 99);
            assertFalse("Modifying the returned map should not affect the parser", 
                    parser.getHeaderMap().containsKey("newKey"));
        }
    }

    @Test
    public void testGetHeaderMap_NoHeaders() throws IOException {
        // CSV content without a header row
        String csvContent = "1,John,30\n2,Jane,25";
        StringReader reader = new StringReader(csvContent);

        // Using CSVFormat.DEFAULT without header configuration
        CSVFormat format = CSVFormat.DEFAULT;

        try (CSVParser parser = CSVParser.parse(csvContent, format)) {
            Map<String, Integer> headerMap = parser.getHeaderMap();

            // Based on implementation, if headerMap is empty, it returns an empty LinkedHashMap
            assertNotNull(headerMap);
            assertTrue("Header map should be empty when no headers are defined", headerMap.isEmpty());
        }
    }
}
